import { useSelector } from 'react-redux';
import { useCallback } from 'react';
import isEqual from 'lodash/isEqual';
import {
  AlertsState,
  selectAlerts,
  selectConfirmedAlertKeys,
  selectFieldAlerts,
  selectGeneralAlerts,
} from '../selectors/alerts';
import {
  Alert,
  setAlertConfirmed as setAlertConfirmedAction,
} from '../ducks/confirm-alerts/confirm-alerts';
import { Severity } from '../helpers/constants/design-system';
import { useDispatch } from '../store/hooks';

const useAlerts = (ownerId: string) => {
  const dispatch = useDispatch();

  const alerts: Alert[] = sortAlertsBySeverity(
    useSelector((state) => selectAlerts(state as AlertsState, ownerId)),
  );

  const confirmedAlertKeys = useSelector(
    (state) => selectConfirmedAlertKeys(state as AlertsState, ownerId),
    isEqual,
  );

  const generalAlerts = sortAlertsBySeverity(
    useSelector((state) => selectGeneralAlerts(state as AlertsState, ownerId)),
  );

  const fieldAlerts = sortAlertsBySeverity(
    useSelector((state) => selectFieldAlerts(state as AlertsState, ownerId)),
  );

  const navigableAlerts = alerts.filter(
    (alert) => !alert.hideFromAlertNavigation,
  );

  const navigableGeneralAlerts = generalAlerts.filter(
    (alert) => !alert.hideFromAlertNavigation,
  );

  const navigableFieldAlerts = fieldAlerts.filter(
    (alert) => !alert.hideFromAlertNavigation,
  );

  const getFieldAlerts = useCallback(
    (field: string | undefined) => {
      if (!field) {
        return [];
      }

      return alerts.filter((alert) => alert.field === field);
    },
    [alerts],
  );

  const getNavigableFieldAlerts = useCallback(
    (field: string | undefined) => {
      if (!field) {
        return [];
      }

      return alerts.filter(
        (alert) => alert.field === field && !alert.hideFromAlertNavigation,
      );
    },
    [alerts],
  );

  const setAlertConfirmed = useCallback(
    (alertKey: string, isConfirmed: boolean) => {
      dispatch(setAlertConfirmedAction(ownerId, alertKey, isConfirmed));
    },
    [dispatch, ownerId],
  );

  const isAlertConfirmed = useCallback(
    (alertKey: string) => {
      return confirmedAlertKeys.includes(alertKey);
    },
    [confirmedAlertKeys],
  );

  const unconfirmedDangerAlerts = alerts.filter(
    (alert) =>
      !isAlertConfirmed(alert.key) &&
      alert.severity === Severity.Danger &&
      !alert.acknowledgeBypass,
  );

  const hasAlerts = alerts.length > 0;

  const dangerAlerts = alerts.filter(
    (alert) => alert.severity === Severity.Danger,
  );

  const hasUnconfirmedDangerAlerts = unconfirmedDangerAlerts.length > 0;

  const unconfirmedFieldDangerAlerts = fieldAlerts.filter(
    (alert) =>
      !isAlertConfirmed(alert.key) &&
      alert.severity === Severity.Danger &&
      !alert.acknowledgeBypass,
  );

  return {
    alerts,
    fieldAlerts,
    generalAlerts,
    getFieldAlerts,
    getNavigableFieldAlerts,
    hasAlerts,
    dangerAlerts,
    hasDangerAlerts: dangerAlerts?.length > 0,
    hasUnconfirmedDangerAlerts,
    isAlertConfirmed,
    navigableAlerts,
    navigableFieldAlerts,
    navigableGeneralAlerts,
    setAlertConfirmed,
    unconfirmedDangerAlerts,
    unconfirmedFieldDangerAlerts,
    hasUnconfirmedFieldDangerAlerts: unconfirmedFieldDangerAlerts.length > 0,
  };
};

function sortAlertsBySeverity(alerts: Alert[]): Alert[] {
  const severityOrder = {
    [Severity.Danger]: 3,
    [Severity.Warning]: 2,
    [Severity.Info]: 1,
    [Severity.Success]: 0,
    [Severity.Disabled]: 0,
  };

  return [...alerts].sort(
    (a, b) => severityOrder[b.severity] - severityOrder[a.severity],
  );
}

export default useAlerts;
